#include <iostream>
#include <map>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Logger {
public:
    void write(const std::string &line) {
        lines_.push_back(line);
    }

    void dump() const {
        for (std::size_t i = 0; i < lines_.size(); i++) {
            std::println("{}. {}", i + 1, lines_[i]);
        }
    }

private:
    std::vector<std::string> lines_;
};

class Account {
public:
    Account(std::string owner, Logger &log) : owner_(std::move(owner)), log_(log) {}

    void deposit(long long n) {
        balance_ += n;
        log_.write(owner_ + ": +" + std::to_string(n));
    }

    void withdraw(long long n) {
        if (n > balance_) {
            log_.write(owner_ + ": отказ " + std::to_string(n));
            return;
        }
        balance_ -= n;
        log_.write(owner_ + ": -" + std::to_string(n));
    }

private:
    std::string owner_;
    Logger &log_;
    long long balance_ = 0;
};

int main() {
    Logger log;
    std::map<std::string, Account> accounts;
    std::string command, name;
    long long n;
    while (std::cin >> command >> name >> n) {
        Account &account = accounts.try_emplace(name, name, log).first->second;
        if (command == "dep") {
            account.deposit(n);
        } else {
            account.withdraw(n);
        }
    }
    log.dump();
    return 0;
}

