#include <iostream>
#include <print>
#include <string>
#include <vector>

class Thermometer {
public:
    void set(double t) {
        value_ = t;
    }

    double value() const {
        return value_;
    }

private:
    double value_ = 20;
};

class Display {
public:
    void connect(const Thermometer *source) {
        source_ = source;
    }

    void disconnect() {
        source_ = nullptr;
    }

    void show() const {
        if (source_ == nullptr) {
            std::println("нет датчика");
        } else {
            std::println("{:.1f} °C", source_->value());
        }
    }

private:
    const Thermometer *source_ = nullptr;
};

int main() {
    std::size_t n;
    std::cin >> n;
    std::vector<Thermometer> sensors(n);
    Display display;
    std::string command;
    while (std::cin >> command) {
        if (command == "set") {
            std::size_t i;
            double t;
            std::cin >> i >> t;
            sensors[i].set(t);
        } else if (command == "connect") {
            std::size_t i;
            std::cin >> i;
            display.connect(&sensors[i]);
        } else if (command == "disconnect") {
            display.disconnect();
        } else {
            display.show();
        }
    }
    return 0;
}

