#include <print>

class Counter {
public:
    void hit() { n_++; }
    int n() const { return n_; }

private:
    int n_ = 0;
};

class Button {
public:
    explicit Button(Counter &c) : c_(c) {}
    void click() { c_.hit(); }

private:
    Counter &c_;
};

int main() {
    Counter total;
    Button a(total), b(total);
    a.click();
    b.click();
    a.click();
    std::println("{}", total.n());
    return 0;
}
